-- pg_morlet 0.3.16 -> 0.3.17 (generated by tests/gen_upgrade.py; do not edit).
-- Interpretation revisions (#600): versioned unit and calibration corrections.
-- Time-anchor trigger functions no longer read their OID argument, so they survive dump and restore (#607).
-- Diagnostic calibration sets (#601), opt-in tables; existing formats unchanged.
\echo Use "ALTER EXTENSION pg_morlet UPDATE TO '0.3.17'" to load this file. \quit

CREATE FUNCTION public.morlet_interpretation_relation(collection regclass)
RETURNS regclass LANGUAGE sql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
  SELECT to_regclass(format('%I.%I',n.nspname,cl.relname||'_interpretation'))
    FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection
$$;

CREATE FUNCTION public.morlet_companion_parent(companion regclass)
RETURNS regclass LANGUAGE sql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
  SELECT k.confrelid::regclass FROM pg_constraint k JOIN pg_attribute a ON a.attrelid=k.conrelid AND a.attnum=k.conkey[1]
    WHERE k.conrelid=companion AND k.contype='f' AND cardinality(k.conkey)=1 AND a.attname='recording_id'
$$;

CREATE FUNCTION public.morlet_enable_interpretation(collection regclass)
RETURNS regclass LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; rel regclass;
BEGIN
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  rel:=public.morlet_interpretation_relation(collection);
  IF rel IS NULL THEN
    EXECUTE format('CREATE TABLE %1$I.%2$I (
      revision_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
      recording_id text NOT NULL REFERENCES %1$I.%3$I(recording_id) ON DELETE CASCADE,
      revision integer NOT NULL CHECK(revision>=1),
      previous_unit text NOT NULL, previous_calibration jsonb,
      unit text NOT NULL, calibration jsonb NOT NULL CHECK(jsonb_typeof(calibration)=''object''),
      reason text NOT NULL CHECK(btrim(reason)<>''''),
      recorded_at timestamptz NOT NULL DEFAULT now(),
      recorded_by text NOT NULL DEFAULT current_user,
      UNIQUE(recording_id,revision))',s,c||'_interpretation',c);
    rel:=format('%I.%I',s,c||'_interpretation')::regclass;
    -- Trigger functions find related tables from the catalog, never from an OID argument: pg_dump keeps trigger
    -- arguments verbatim, and OIDs differ after a restore.
    -- The rules hold for direct SQL too: history is append-only, and the recording's unit or calibration can only
    -- change together with a revision that records it.
    EXECUTE format('CREATE TRIGGER morlet_interpretation_insert BEFORE INSERT ON %s
      FOR EACH ROW EXECUTE FUNCTION public.morlet_interpretation_insert()',rel);
    EXECUTE format('CREATE CONSTRAINT TRIGGER morlet_interpretation_applied AFTER INSERT ON %s
      DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.morlet_interpretation_applied()',rel);
    EXECUTE format('CREATE TRIGGER morlet_interpretation_append_only BEFORE UPDATE OR DELETE ON %s
      FOR EACH ROW EXECUTE FUNCTION public.morlet_interpretation_append_only()',rel);
    EXECUTE format('CREATE TRIGGER morlet_interpretation_no_truncate BEFORE TRUNCATE ON %s
      FOR EACH STATEMENT EXECUTE FUNCTION public.morlet_interpretation_append_only()',rel);
    EXECUTE format('CREATE TRIGGER morlet_interpretation_guard BEFORE UPDATE OF unit,metadata ON %s FOR EACH ROW
      WHEN (OLD.unit IS DISTINCT FROM NEW.unit OR OLD.metadata->''calibration'' IS DISTINCT FROM NEW.metadata->''calibration'')
      EXECUTE FUNCTION public.morlet_interpretation_guard()',collection);
  END IF;
  PERFORM public.morlet_bind_label_interpretation(collection);
  IF public.morlet_row_security_enabled(collection) THEN PERFORM public.morlet_enable_row_security(collection); END IF;
  RETURN rel;
END $$;

CREATE FUNCTION public.morlet_bind_label_interpretation(collection regclass)
RETURNS void LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; labels regclass;
BEGIN
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  labels:=to_regclass(format('%I.%I',s,c||'_labels'));
  IF labels IS NULL OR public.morlet_interpretation_relation(collection) IS NULL
    OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=labels AND tgname='morlet_label_interpretation') THEN RETURN; END IF;
  EXECUTE format('ALTER TABLE %s ADD COLUMN interpretation_revision integer CHECK(interpretation_revision>=0)',labels);
  EXECUTE format('CREATE TRIGGER morlet_label_interpretation BEFORE INSERT OR UPDATE OF interpretation_revision ON %s
    FOR EACH ROW EXECUTE FUNCTION public.morlet_label_interpretation()',labels);
END $$;

CREATE FUNCTION public.morlet_label_interpretation()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass; current_revision integer;
BEGIN
  IF TG_OP='UPDATE' THEN NEW.interpretation_revision:=OLD.interpretation_revision; RETURN NEW; END IF;
  rel:=public.morlet_interpretation_relation(public.morlet_companion_parent(TG_RELID));
  IF rel IS NOT NULL AND has_table_privilege(rel,'SELECT') THEN
    EXECUTE format('SELECT coalesce(max(revision),0) FROM %s WHERE recording_id=$1',rel)
      INTO current_revision USING NEW.recording_id;
  END IF;
  NEW.interpretation_revision:=current_revision;
  RETURN NEW;
END $$;

CREATE FUNCTION public.morlet_interpretation_append_only()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE parent boolean;
BEGIN
  IF TG_OP='DELETE' AND pg_trigger_depth()>1 THEN
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s WHERE recording_id=$1)',public.morlet_companion_parent(TG_RELID))
      INTO parent USING OLD.recording_id;
    IF NOT parent THEN RETURN OLD; END IF;
  END IF;
  RAISE EXCEPTION 'interpretation history is append-only: correct it with morlet_correct_interpretation';
END $$;

CREATE FUNCTION public.morlet_interpretation_insert()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE cur_unit text; cur_cal jsonb; cur integer; last_unit text; last_cal jsonb;
BEGIN
  EXECUTE format('SELECT unit,metadata->''calibration'' FROM %s WHERE recording_id=$1 FOR UPDATE',public.morlet_companion_parent(TG_RELID))
    INTO cur_unit,cur_cal USING NEW.recording_id;
  IF cur_unit IS NULL THEN RAISE EXCEPTION 'recording does not exist or is not visible'; END IF;
  EXECUTE format('SELECT coalesce(max(revision),0) FROM %s WHERE recording_id=$1',TG_RELID::regclass) INTO cur USING NEW.recording_id;
  IF cur>0 THEN     -- the history stays one chain: each revision replaces what the previous one applied
    EXECUTE format('SELECT unit,calibration FROM %s WHERE recording_id=$1 AND revision=$2',TG_RELID::regclass)
      INTO last_unit,last_cal USING NEW.recording_id,cur;
    IF last_unit IS DISTINCT FROM cur_unit OR last_cal IS DISTINCT FROM cur_cal THEN
      RAISE EXCEPTION 'interpretation revision % is not applied to recording %',cur,NEW.recording_id;
    END IF;
  END IF;
  IF NEW.revision<>cur+1 THEN RAISE EXCEPTION 'interpretation revision must be %',cur+1; END IF;
  IF NEW.unit=cur_unit AND NEW.calibration IS NOT DISTINCT FROM cur_cal THEN
    RAISE EXCEPTION 'an interpretation revision must change the unit or the calibration';
  END IF;
  NEW.previous_unit:=cur_unit; NEW.previous_calibration:=cur_cal;
  NEW.recorded_at:=now(); NEW.recorded_by:=current_user;
  RETURN NEW;
END $$;

CREATE FUNCTION public.morlet_interpretation_applied()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE cur_unit text; cur_cal jsonb; latest integer;
BEGIN
  EXECUTE format('SELECT unit,metadata->''calibration'' FROM %s WHERE recording_id=$1',public.morlet_companion_parent(TG_RELID))
    INTO cur_unit,cur_cal USING NEW.recording_id;
  IF cur_unit IS NULL THEN RETURN NULL; END IF;     -- the recording was deleted, and its history with it
  EXECUTE format('SELECT max(revision) FROM %s WHERE recording_id=$1',TG_RELID::regclass) INTO latest USING NEW.recording_id;
  IF NEW.revision=latest AND (cur_unit IS DISTINCT FROM NEW.unit OR cur_cal IS DISTINCT FROM NEW.calibration) THEN
    RAISE EXCEPTION 'interpretation revision % does not match recording %',NEW.revision,NEW.recording_id;
  END IF;
  RETURN NULL;
END $$;

CREATE FUNCTION public.morlet_interpretation_guard()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass; rev_unit text; rev_cal jsonb;
BEGIN
  rel:=public.morlet_interpretation_relation(TG_RELID);
  IF rel IS NULL THEN RAISE EXCEPTION 'unit and calibration change only through morlet_correct_interpretation'; END IF;
  EXECUTE format('SELECT unit,calibration FROM %s WHERE recording_id=$1 ORDER BY revision DESC LIMIT 1',rel)
    INTO rev_unit,rev_cal USING NEW.recording_id;
  IF rev_unit IS NULL OR rev_unit IS DISTINCT FROM NEW.unit OR rev_cal IS DISTINCT FROM NEW.metadata->'calibration' THEN
    RAISE EXCEPTION 'unit and calibration change only through morlet_correct_interpretation';
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION public.morlet_correct_interpretation(collection regclass,recording_id text,unit text,calibration jsonb,reason text)
RETURNS integer LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass; cur_unit text; cur_cal jsonb; cur integer;
BEGIN
  rel:=public.morlet_interpretation_relation(collection);
  IF rel IS NULL THEN RAISE EXCEPTION 'interpretation history is not enabled for this collection (morlet_enable_interpretation)'; END IF;
  IF jsonb_typeof(calibration)<>'object' THEN RAISE EXCEPTION 'calibration must be a JSON object'; END IF;
  IF btrim(reason)='' THEN RAISE EXCEPTION 'a correction needs a reason'; END IF;
  EXECUTE format('SELECT r.unit,r.metadata->''calibration'' FROM %s r WHERE r.recording_id=$1 FOR UPDATE',collection)
    INTO cur_unit,cur_cal USING recording_id;
  IF cur_unit IS NULL THEN RAISE EXCEPTION 'recording does not exist or is not visible'; END IF;
  EXECUTE format('SELECT coalesce(max(i.revision),0) FROM %s i WHERE i.recording_id=$1',rel) INTO cur USING recording_id;
  IF cur_unit=unit AND cur_cal IS NOT DISTINCT FROM calibration THEN RETURN cur; END IF;
  EXECUTE format('INSERT INTO %s(recording_id,revision,previous_unit,previous_calibration,unit,calibration,reason)
    VALUES ($1,$2,$3,$4,$5,$6,$7)',rel) USING recording_id,cur+1,cur_unit,cur_cal,unit,calibration,reason;
  EXECUTE format('UPDATE %s r SET unit=$2,metadata=jsonb_set(r.metadata,''{calibration}'',$3,true) WHERE r.recording_id=$1',collection)
    USING recording_id,unit,calibration;
  RETURN cur+1;
END $$;

CREATE FUNCTION public.morlet_interpretation_revisions(collection regclass,recording_ids text[])
RETURNS TABLE(recording_id text,revision integer)
LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass;
BEGIN
  rel:=public.morlet_interpretation_relation(collection);
  IF rel IS NULL OR NOT has_table_privilege(rel,'SELECT') THEN RETURN; END IF;
  RETURN QUERY EXECUTE format('SELECT r.recording_id,coalesce((SELECT max(i.revision) FROM %s i
    WHERE i.recording_id=r.recording_id),0)::integer FROM %s r WHERE r.recording_id=ANY($1) ORDER BY 1',rel,collection)
    USING recording_ids;
END $$;

CREATE FUNCTION public.morlet_interpretation_history(collection regclass,recording_id text)
RETURNS TABLE(revision integer,previous_unit text,previous_calibration jsonb,unit text,calibration jsonb,reason text,
  recorded_at timestamptz,recorded_by text)
LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass;
BEGIN
  rel:=public.morlet_interpretation_relation(collection);
  IF rel IS NULL THEN RAISE EXCEPTION 'interpretation history is not enabled for this collection (morlet_enable_interpretation)'; END IF;
  RETURN QUERY EXECUTE format('SELECT i.revision,i.previous_unit,i.previous_calibration,i.unit,i.calibration,i.reason,
    i.recorded_at,i.recorded_by FROM %s i WHERE i.recording_id=$1 ORDER BY i.revision',rel) USING recording_id;
END $$;

CREATE FUNCTION public.morlet_interpretation_review(collection regclass,recording_id text DEFAULT NULL,max_rows integer DEFAULT 1000)
RETURNS TABLE(label_id bigint,label_recording_id text,start_sample bigint,end_sample bigint,label text,
  label_revision integer,current_revision integer,status text,truncated boolean)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass; labels regclass;
BEGIN
  IF collection IS NULL OR max_rows IS NULL OR max_rows NOT BETWEEN 1 AND 100000 THEN
    RAISE EXCEPTION 'a collection and max_rows in 1..100000 are required';
  END IF;
  rel:=public.morlet_interpretation_relation(collection);
  IF rel IS NULL THEN RAISE EXCEPTION 'interpretation history is not enabled for this collection (morlet_enable_interpretation)'; END IF;
  SELECT to_regclass(format('%I.%I',n.nspname,cl.relname||'_labels')) INTO labels
    FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  IF labels IS NULL THEN RETURN; END IF;
  RETURN QUERY EXECUTE format('WITH cur AS (SELECT i.recording_id,max(i.revision) AS revision FROM %s i
      WHERE $1::text IS NULL OR i.recording_id=$1 GROUP BY i.recording_id),
    due AS (SELECT l.label_id,l.recording_id,l.start_sample,l.end_sample,l.label,l.interpretation_revision,c.revision
      FROM %s l JOIN cur c ON c.recording_id=l.recording_id
      WHERE NOT l.retracted AND (l.interpretation_revision IS NULL OR l.interpretation_revision<c.revision)
      ORDER BY l.recording_id,l.start_sample,l.label_id LIMIT $2+1)
    SELECT d.label_id,d.recording_id,d.start_sample,d.end_sample,d.label,d.interpretation_revision,d.revision,
      CASE WHEN d.interpretation_revision IS NULL THEN ''unversioned'' ELSE ''stale'' END,
      (SELECT count(*) FROM due)>$2
    FROM due d ORDER BY d.recording_id,d.start_sample,d.label_id LIMIT $2',rel,labels) USING recording_id,max_rows;
END $$;

CREATE FUNCTION public.morlet_calibration_relation(collection regclass)
RETURNS regclass LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass;
BEGIN
  SELECT to_regclass(format('%I.%I',n.nspname,c.relname||'_calibration_sets')) INTO rel
    FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=collection;
  IF rel IS NULL THEN RAISE EXCEPTION 'calibration sets are not enabled'; END IF;
  RETURN rel;
END $$;

CREATE FUNCTION public.morlet_calibration_capture(collection regclass,members jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog
  SET timezone='UTC' SET extra_float_digits=3 AS $$
DECLARE rel record; m jsonb; rec jsonb; lab jsonb; contexts jsonb; acquisitions jsonb;
  result jsonb:='[]'; rid text; lo bigint; hi bigint; label_id bigint; total bigint:=0;
  s text; c text; channels regclass; raw bytea;
BEGIN
  IF jsonb_typeof(members) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'members must be an array'; END IF;
  IF jsonb_array_length(members) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'expected 1..100 members'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(members)) <>
     (SELECT count(DISTINCT (value->'recording_id',value->'start_sample',value->'end_sample')) FROM jsonb_array_elements(members)) THEN
    RAISE EXCEPTION 'duplicate calibration member';
  END IF;
  SELECT * INTO rel FROM public.morlet_context_relations(collection);
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  channels:=to_regclass(format('%I.%I',s,c||'_acq_channels'));
  FOR m IN SELECT value FROM jsonb_array_elements(members) ORDER BY value::text COLLATE "C" LOOP
    IF jsonb_typeof(m) IS DISTINCT FROM 'object' OR
       (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(m) key) IS DISTINCT FROM
       ARRAY['end_sample','label_id','recording_id','start_sample']::text[] THEN
      RAISE EXCEPTION 'member requires exactly recording_id, start_sample, end_sample, label_id';
    END IF;
    IF jsonb_typeof(m->'recording_id') IS DISTINCT FROM 'string' OR
       jsonb_typeof(m->'start_sample') IS DISTINCT FROM 'number' OR
       jsonb_typeof(m->'end_sample') IS DISTINCT FROM 'number' OR
       jsonb_typeof(m->'label_id') IS DISTINCT FROM 'number' OR (m->>'start_sample') !~ '^[0-9]+$' OR (m->>'end_sample') !~ '^[0-9]+$' OR
       (m->>'label_id') !~ '^[0-9]+$' OR m->>'start_sample' IS NULL OR
       m->>'end_sample' IS NULL OR m->>'label_id' IS NULL THEN RAISE EXCEPTION 'invalid member fields'; END IF;
    rid:=m->>'recording_id'; lo:=(m->>'start_sample')::bigint; hi:=(m->>'end_sample')::bigint;
    label_id:=(m->>'label_id')::bigint;
    IF hi<=lo OR hi-lo>1000000 THEN RAISE EXCEPTION 'each member requires 1..1000000 samples'; END IF;
    total:=total+hi-lo;
    IF total>4000000 THEN RAISE EXCEPTION 'calibration set exceeds 4000000 samples'; END IF;
    EXECUTE format('SELECT jsonb_build_object(''sample_rate_hz'',sample_rate_hz,''channel'',channel,''unit'',unit,
      ''metadata'',metadata) FROM %s WHERE recording_id=$1',collection) INTO rec USING rid;
    IF rec IS NULL THEN RAISE EXCEPTION 'member recording unavailable'; END IF;
    EXECUTE format('SELECT to_jsonb(l) FROM %s l WHERE label_id=$1 AND recording_id=$2
      AND start_sample<=$3 AND end_sample>=$4 AND NOT retracted',rel.labels)
      INTO lab USING label_id,rid,lo,hi;
    IF lab IS NULL THEN RAISE EXCEPTION 'member requires a visible active label covering its interval'; END IF;
    EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.ctx_id),''[]''::jsonb) FROM %1$s x
      WHERE recording_id=$1 AND start_sample<$3 AND coalesce(end_sample,start_sample+1)>$2
      AND NOT retracted AND NOT EXISTS(SELECT 1 FROM %1$s y WHERE y.supersedes=x.ctx_id)',rel.ctx)
      INTO contexts USING rid,lo,hi;
    acquisitions:='[]';
    IF channels IS NOT NULL THEN
      EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.acquisition_id),''[]''::jsonb)
        FROM %s x WHERE recording_id=$1',channels) INTO acquisitions USING rid;
    END IF;
    raw:=public.morlet_read_interval_raw(collection,rid,lo,hi);
    result:=result||jsonb_build_array(m||jsonb_build_object('recording',rec,'label',lab,'context',contexts,
      'acquisitions',acquisitions,'acquisition_identity',CASE WHEN acquisitions='[]'::jsonb THEN 'unknown' ELSE 'recorded' END,
      'sample_sha256',encode(sha256(raw),'hex'),'sample_encoding','ieee754-f64-le',
      'time_axis_version',public.morlet_time_axis_version(collection,rid),
      'interpretation_revision','unversioned','label_revision','unversioned',
      'availability','unknown'));
  END LOOP;
  RETURN jsonb_build_object('format','morlet-calibration-v1','collection',collection::text,
    'representation',jsonb_build_object('kind','raw','version',1),'members',result,
    'causal_replay',false,'retention','reference-only');
END $$;

CREATE FUNCTION public.morlet_calibration_guard()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE coll regclass:=TG_ARGV[0]::regclass; captured jsonb;
BEGIN
  IF TG_OP='TRUNCATE' OR TG_OP='DELETE' THEN RAISE EXCEPTION 'calibration revisions cannot be removed'; END IF;
  IF current_setting('transaction_isolation') NOT IN ('repeatable read','serializable') THEN
    RAISE EXCEPTION 'calibration writes require REPEATABLE READ or SERIALIZABLE';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.approved THEN RAISE EXCEPTION 'create a draft before approval'; END IF;
    NEW.created_by:=current_user; NEW.created_at:=transaction_timestamp();
  ELSE
    IF OLD.approved THEN RAISE EXCEPTION 'approved calibration revision is immutable; create another revision'; END IF;
    IF (NEW.set_id,NEW.revision) IS DISTINCT FROM (OLD.set_id,OLD.revision) THEN
      RAISE EXCEPTION 'calibration revision identity is immutable';
    END IF;
    NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at;
  END IF;
  IF NEW.approved THEN
    IF NOT pg_has_role(current_user,TG_ARGV[1],'MEMBER') THEN
      RAISE EXCEPTION 'calibration approval requires membership of role %',TG_ARGV[1] USING ERRCODE='42501';
    END IF;
    IF NEW.members IS DISTINCT FROM OLD.members THEN RAISE EXCEPTION 'approval cannot edit membership'; END IF;
    IF NEW.approval_reason IS NULL OR btrim(NEW.approval_reason)='' THEN RAISE EXCEPTION 'approval reason required'; END IF;
    captured:=public.morlet_calibration_capture(coll,NEW.members);
    IF captured IS DISTINCT FROM OLD.manifest THEN RAISE EXCEPTION 'draft evidence changed; explicitly refresh the draft before approval'; END IF;
    NEW.approved_by:=current_user; NEW.approved_at:=transaction_timestamp();
  ELSE
    NEW.approved_by:=NULL; NEW.approved_at:=NULL; NEW.approval_reason:=NULL;
    captured:=public.morlet_calibration_capture(coll,NEW.members);
  END IF;
  -- All derived/audit columns are database generated, including on direct SQL writes.
  SELECT jsonb_agg(value ORDER BY value::text COLLATE "C") INTO NEW.members FROM jsonb_array_elements(NEW.members);
  NEW.manifest:=captured;
  NEW.manifest_text:=captured::text;
  NEW.manifest_sha256:=encode(sha256(convert_to(NEW.manifest_text,'UTF8')),'hex');
  SELECT array_agg(DISTINCT value->>'recording_id' ORDER BY value->>'recording_id') INTO NEW.recording_ids
    FROM jsonb_array_elements(NEW.members);
  RETURN NEW;
END $$;

CREATE FUNCTION public.morlet_enable_calibration_sets(collection regclass,approver_role regrole)
RETURNS regclass LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; rel regclass; owner oid; approver_name text;
BEGIN
  SELECT rolname INTO STRICT approver_name FROM pg_roles WHERE oid=approver_role;
  SELECT n.nspname,cl.relname,cl.relowner INTO s,c,owner FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
    WHERE cl.oid=collection;
  IF NOT pg_has_role(current_user,owner,'USAGE') THEN RAISE EXCEPTION 'collection owner required' USING ERRCODE='42501'; END IF;
  IF octet_length(c)>45 THEN RAISE EXCEPTION 'collection name too long for calibration companion table'; END IF;
  PERFORM public.morlet_context_relations(collection);
  rel:=to_regclass(format('%I.%I',s,c||'_calibration_sets'));
  IF rel IS NOT NULL THEN
    -- Do not silently change the approval authority on an idempotent enable call.
    IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=rel AND tgname='morlet_calibration_guard'
      AND tgargs=convert_to(collection::text,'UTF8')||decode('00','hex')||
        convert_to(approver_name,'UTF8')||decode('00','hex')) THEN
      RAISE EXCEPTION 'calibration sets already enabled with another authority or collection identity';
    END IF;
    RETURN rel;
  END IF;
  EXECUTE format('CREATE TABLE %I.%I (
    set_id text NOT NULL CHECK(length(set_id) BETWEEN 1 AND 200), revision integer NOT NULL CHECK(revision>0),
    members jsonb NOT NULL, recording_ids text[] NOT NULL, manifest jsonb NOT NULL,
    manifest_text text NOT NULL, manifest_sha256 text NOT NULL,
    created_by name NOT NULL, created_at timestamptz NOT NULL,
    approved boolean NOT NULL DEFAULT false, approved_by name, approved_at timestamptz, approval_reason text,
    PRIMARY KEY(set_id,revision))',s,c||'_calibration_sets');
  rel:=to_regclass(format('%I.%I',s,c||'_calibration_sets'));
  EXECUTE format('CREATE TRIGGER morlet_calibration_guard BEFORE INSERT OR UPDATE OR DELETE ON %s
    FOR EACH ROW EXECUTE FUNCTION public.morlet_calibration_guard(%L,%L)',rel,collection::text,approver_name);
  EXECUTE format('CREATE TRIGGER morlet_calibration_truncate BEFORE TRUNCATE ON %s
    FOR EACH STATEMENT EXECUTE FUNCTION public.morlet_calibration_guard(%L,%L)',rel,collection::text,approver_name);
  IF public.morlet_row_security_enabled(collection) THEN PERFORM public.morlet_enable_row_security(collection); END IF;
  RETURN rel;
END $$;

CREATE FUNCTION public.morlet_put_calibration_set(collection regclass,set_id text,revision integer,members jsonb,
  replace_draft boolean DEFAULT false,decision_at timestamptz DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass; existing record; canonical jsonb; result jsonb;
BEGIN
  IF collection IS NULL OR set_id IS NULL OR revision IS NULL OR members IS NULL OR replace_draft IS NULL THEN
    RAISE EXCEPTION 'calibration arguments cannot be NULL'; END IF;
  IF decision_at IS NOT NULL THEN RAISE EXCEPTION 'historical availability is not tracked; as-of calibration is unsupported'; END IF;
  rel:=public.morlet_calibration_relation(collection);
  SELECT jsonb_agg(value ORDER BY value::text COLLATE "C") INTO canonical FROM jsonb_array_elements(members);
  EXECUTE format('SELECT * FROM %s WHERE set_id=$1 AND revision=$2 FOR UPDATE',rel) INTO existing USING set_id,revision;
  IF existing.set_id IS NOT NULL THEN
    IF existing.members=canonical AND NOT replace_draft THEN RETURN to_jsonb(existing); END IF;
    IF NOT replace_draft THEN RAISE EXCEPTION 'conflicting calibration retry'; END IF;
    EXECUTE format('UPDATE %s AS x SET members=$3 WHERE set_id=$1 AND revision=$2 RETURNING to_jsonb(x)',rel)
      INTO result USING set_id,revision,members;
  ELSE
    EXECUTE format('INSERT INTO %s AS x(set_id,revision,members) VALUES ($1,$2,$3) ON CONFLICT DO NOTHING RETURNING to_jsonb(x)',rel)
      INTO result USING set_id,revision,members;
  END IF;
  IF result IS NULL THEN RAISE EXCEPTION 'calibration revision unavailable or conflicting'; END IF;
  RETURN result;
END $$;

CREATE FUNCTION public.morlet_approve_calibration_set(collection regclass,set_id text,revision integer,expected_digest text,reason text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE rel regclass:=public.morlet_calibration_relation(collection); existing record; result jsonb;
BEGIN
  EXECUTE format('SELECT * FROM %s WHERE set_id=$1 AND revision=$2 FOR UPDATE',rel) INTO existing USING set_id,revision;
  IF existing.set_id IS NULL THEN RAISE EXCEPTION 'calibration revision unavailable'; END IF;
  IF existing.manifest_sha256<>expected_digest THEN RAISE EXCEPTION 'draft digest changed; review again'; END IF;
  IF existing.approved THEN
    IF existing.approval_reason=reason AND existing.approved_by=current_user THEN RETURN to_jsonb(existing); END IF;
    RAISE EXCEPTION 'conflicting approval retry';
  END IF;
  EXECUTE format('UPDATE %s AS x SET approved=true,approval_reason=$3 WHERE set_id=$1 AND revision=$2 RETURNING to_jsonb(x)',rel)
    INTO result USING set_id,revision,reason;
  RETURN result;
END $$;

CREATE FUNCTION public.morlet_get_calibration_set(collection regclass,set_id text,revision integer)
RETURNS jsonb LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE result jsonb;
BEGIN
  EXECUTE format('SELECT to_jsonb(x) FROM %s x WHERE set_id=$1 AND revision=$2',public.morlet_calibration_relation(collection))
    INTO result USING set_id,revision;
  IF result IS NULL THEN RAISE EXCEPTION 'calibration revision unavailable'; END IF;
  RETURN result;
END $$;

CREATE FUNCTION public.morlet_resolve_calibration_set(collection regclass,set_id text,revision integer)
RETURNS jsonb LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE saved jsonb; current_manifest jsonb; statuses jsonb:='[]'; m jsonb; item jsonb; fresh jsonb;
BEGIN
  saved:=public.morlet_get_calibration_set(collection,set_id,revision);
  FOR m IN SELECT value FROM jsonb_array_elements(saved->'manifest'->'members') LOOP
    item:=jsonb_build_object('recording_id',m->'recording_id','start_sample',m->'start_sample',
      'end_sample',m->'end_sample','label_id',m->'label_id');
    BEGIN
      current_manifest:=public.morlet_calibration_capture(collection,jsonb_build_array(item));
      fresh:=current_manifest->'members'->0;
      statuses:=statuses||jsonb_build_array(item||jsonb_build_object('status',
        CASE WHEN fresh=m THEN 'unchanged' ELSE 'changed' END));
    EXCEPTION WHEN OTHERS THEN
      -- Do not turn corruption, permissions, cancellation or operational failures into missing evidence.
      IF SQLSTATE='P0001' AND (SQLERRM='member recording unavailable' OR
          SQLERRM='member requires a visible active label covering its interval' OR
          SQLERRM='source interval is incomplete or not fully visible' OR
          SQLERRM LIKE 'samples of recording % were compacted to level %') THEN
        statuses:=statuses||jsonb_build_array(item||jsonb_build_object('status','unavailable'));
      ELSE RAISE; END IF;
    END;
  END LOOP;
  RETURN jsonb_build_object('set_id',set_id,'revision',revision,'approved',saved->'approved',
    'manifest_sha256',saved->'manifest_sha256','members',statuses,
    'needs_review',EXISTS(SELECT 1 FROM jsonb_array_elements(statuses) x WHERE x->>'status'<>'unchanged'));
END $$;

CREATE OR REPLACE FUNCTION public.morlet_enable_context(collection regclass)
RETURNS void LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text;
BEGIN
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  EXECUTE format('CREATE TABLE %1$I.%2$I (
    ctx_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    recording_id text NOT NULL REFERENCES %1$I.%3$I(recording_id) ON DELETE CASCADE,
    kind text NOT NULL CHECK(kind IN (''interval'',''event'')),
    key text NOT NULL CHECK(key<>''''),
    value jsonb NOT NULL,
    start_sample bigint NOT NULL CHECK(start_sample>=0),
    end_sample bigint CHECK(end_sample>start_sample),
    batch_id text NOT NULL,
    supersedes bigint REFERENCES %1$I.%2$I(ctx_id),
    retracted boolean NOT NULL DEFAULT false,
    recorded_at timestamptz NOT NULL DEFAULT now(),
    recorded_by text NOT NULL DEFAULT current_user,
    CHECK((kind=''event'')=(end_sample IS NULL)))',s,c||'_ctx',c);
  EXECUTE format('CREATE INDEX ON %I.%I(recording_id,key,start_sample)',s,c||'_ctx');
  EXECUTE format('CREATE UNIQUE INDEX ON %I.%I(supersedes) WHERE supersedes IS NOT NULL',s,c||'_ctx');
  -- morlet_add_context looks a batch up by its id on every call (#414)
  EXECUTE format('CREATE INDEX ON %I.%I(batch_id)',s,c||'_ctx');
  EXECUTE format('CREATE TABLE %1$I.%2$I (
    segment_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    recording_id text NOT NULL REFERENCES %1$I.%3$I(recording_id) ON DELETE CASCADE,
    start_sample bigint NOT NULL CHECK(start_sample>=0),
    end_sample bigint NOT NULL CHECK(end_sample>start_sample),
    context jsonb NOT NULL, occurrence jsonb NOT NULL, ctx_ids bigint[] NOT NULL, spec jsonb NOT NULL,
    stale boolean NOT NULL DEFAULT false,
    UNIQUE(recording_id,start_sample,end_sample,spec))',s,c||'_ctx_segments',c);
  EXECUTE format('CREATE TABLE %1$I.%2$I (
    segment_id bigint NOT NULL REFERENCES %1$I.%3$I(segment_id) ON DELETE CASCADE,
    representation text NOT NULL, vals float8[] COMPRESSION pglz NOT NULL,
    PRIMARY KEY(segment_id,representation))',s,c||'_ctx_values',c||'_ctx_segments');
  EXECUTE format('CREATE TABLE %1$I.%2$I (
    label_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    recording_id text NOT NULL REFERENCES %1$I.%3$I(recording_id) ON DELETE CASCADE,
    start_sample bigint NOT NULL CHECK(start_sample>=0),
    end_sample bigint NOT NULL CHECK(end_sample>start_sample),
    label text NOT NULL CHECK(label<>''''), note text NOT NULL DEFAULT '''',
    author text NOT NULL DEFAULT current_user, created_at timestamptz NOT NULL DEFAULT now(),
    retracted boolean NOT NULL DEFAULT false)',s,c||'_labels',c);
  PERFORM public.morlet_label_glossary_table(collection);
  PERFORM public.morlet_set_value_rules(collection,'simple-v2');
  PERFORM public.morlet_bind_label_interpretation(collection);
  IF public.morlet_row_security_enabled(collection) THEN PERFORM public.morlet_enable_row_security(collection); END IF;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_enable_row_security(collection regclass)
RETURNS integer LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; t record; covered integer:=0; cond text; chk text;
BEGIN
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  FOR t IN SELECT cl.relname FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace
      WHERE n.nspname=s AND cl.relkind='r' AND (cl.relname IN (c||'_chunks',c||'_segments',c||'_envelopes',c||'_ctx',
        c||'_ctx_segments',c||'_ctx_values',c||'_labels',c||'_acq',c||'_acq_channels',c||'_rollups',
        c||'_episodes',c||'_ledger',c||'_kept_summaries',c||'_memory_runs',c||'_time_anchors',c||'_interpretation',c||'_calibration_sets') OR (left(cl.relname,length(c)+8)=c||'_probes_' AND substr(cl.relname,length(c)+9) ~ '^[0-9]+$'))
      ORDER BY cl.relname LOOP
    IF t.relname=c||'_calibration_sets' THEN
      -- A manifest is indivisible: never disclose a partly visible multi-recording set.
      cond:=format('recording_ids <@ ARRAY(SELECT x.recording_id FROM %s x)',collection);
      chk:=cond;
    ELSIF t.relname=c||'_ctx_values' THEN
      cond:=format('EXISTS(SELECT 1 FROM %I.%I x WHERE x.segment_id=%I.segment_id)',s,c||'_ctx_segments',t.relname);
      chk:=cond;
    ELSIF t.relname=c||'_acq' THEN
      -- visible through a visible channel, and to its creator until it has one (inserting an acquisition
      -- precedes its channels)
      -- (the channel lookup runs in a function: the channel policy refers to this table, and a subquery here
      -- would make the policies recursive)
      cond:=format('public.morlet_acquisition_has_visible_channel(%L::regclass,%I.acquisition_id)
        OR public.morlet_inserted_by_current_transaction(%I.xmin)',format('%I.%I',s,c||'_acq_channels'),t.relname,t.relname);
      chk:='true';
    ELSIF t.relname=c||'_memory_runs' THEN
      -- Episodic memory (#438): a run has no recording of its own and may span several, so it is visible to the
      -- role that started it; its ledger rows follow their recordings. Older tables get the column here.
      EXECUTE format('ALTER TABLE %I.%I ADD COLUMN IF NOT EXISTS started_by name NOT NULL DEFAULT current_user',s,t.relname);
      cond:=format('%I.started_by = current_user',t.relname);
      chk:=cond;
    ELSIF t.relname=c||'_acq_channels' THEN
      -- a channel row follows its recording; adding or moving one also needs its acquisition to be visible,
      -- so a recording cannot join another tenant's acquisition by naming its ID (a foreign key is not
      -- an authorization check)
      cond:=format('%I.recording_id = ANY (ARRAY(SELECT x.recording_id FROM %s x))',t.relname,collection);
      chk:=format('%s AND EXISTS(SELECT 1 FROM %I.%I a WHERE a.acquisition_id=%I.acquisition_id)',
        cond,s,c||'_acq',t.relname);
    ELSE
      -- An uncorrelated ARRAY(...) becomes an InitPlan, which keeps scans parallel; a correlated
      -- EXISTS compiled to a parallel-restricted SubPlan and made exact search 3x slower.
      cond:=format('%I.recording_id = ANY (ARRAY(SELECT x.recording_id FROM %s x))',t.relname,collection);
      chk:=cond;
    END IF;
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY',s,t.relname);
    EXECUTE format('DROP POLICY IF EXISTS morlet_follows_recording ON %I.%I',s,t.relname);
    EXECUTE format('CREATE POLICY morlet_follows_recording ON %I.%I USING (%s) WITH CHECK (%s)',s,t.relname,cond,chk);
    covered:=covered+1;
  END LOOP;
  RETURN covered;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_enable_time_anchors(collection regclass)
RETURNS regclass LANGUAGE plpgsql VOLATILE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE s text; c text; rel regclass;
BEGIN
  SELECT n.nspname,cl.relname INTO s,c FROM pg_class cl JOIN pg_namespace n ON n.oid=cl.relnamespace WHERE cl.oid=collection;
  rel:=to_regclass(format('%I.%I',s,c||'_time_anchors'));
  IF rel IS NULL THEN
    EXECUTE format('CREATE TABLE %1$I.%2$I (
      anchor_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
      recording_id text NOT NULL REFERENCES %1$I.%3$I(recording_id) ON DELETE CASCADE,
      sample_offset bigint NOT NULL CHECK(sample_offset>=0),
      utc_ns bigint NOT NULL,
      uncertainty_ns bigint NOT NULL CHECK(uncertainty_ns>=0),
      source text NOT NULL CHECK(source<>''''),
      break_before boolean NOT NULL DEFAULT false,
      batch_id text NOT NULL CHECK(batch_id<>''''),
      revision integer NOT NULL DEFAULT 1 CHECK(revision>=1),
      supersedes bigint REFERENCES %1$I.%2$I(anchor_id),
      retracted boolean NOT NULL DEFAULT false,
      recorded_at timestamptz NOT NULL DEFAULT now(),
      recorded_by text NOT NULL DEFAULT current_user)',s,c||'_time_anchors',c);
    EXECUTE format('CREATE INDEX ON %I.%I(recording_id,sample_offset)',s,c||'_time_anchors');
    EXECUTE format('CREATE INDEX ON %I.%I(batch_id)',s,c||'_time_anchors');
    EXECUTE format('CREATE UNIQUE INDEX ON %I.%I(supersedes) WHERE supersedes IS NOT NULL',s,c||'_time_anchors');
    rel:=format('%I.%I',s,c||'_time_anchors')::regclass;
    -- The rules hold for direct SQL too: every insert is checked per statement, and rows are never changed or
    -- removed (revisions and retractions are new rows), except when their recording is deleted. The triggers take no
    -- arguments: pg_dump keeps arguments verbatim, and an OID changes on restore (#607).
    EXECUTE format('CREATE TRIGGER morlet_time_anchors_lock BEFORE INSERT ON %s
      FOR EACH ROW EXECUTE FUNCTION public.morlet_time_anchors_lock()',rel);
    EXECUTE format('CREATE TRIGGER morlet_time_anchors_check AFTER INSERT ON %s REFERENCING NEW TABLE AS morlet_new_anchors
      FOR EACH STATEMENT EXECUTE FUNCTION public.morlet_time_anchors_inserted()',rel);
    EXECUTE format('CREATE TRIGGER morlet_time_anchors_append_only BEFORE UPDATE OR DELETE ON %s
      FOR EACH ROW EXECUTE FUNCTION public.morlet_time_anchors_append_only()',rel);
    EXECUTE format('CREATE TRIGGER morlet_time_anchors_no_truncate BEFORE TRUNCATE ON %s
      FOR EACH STATEMENT EXECUTE FUNCTION public.morlet_time_anchors_append_only()',rel);
  END IF;
  IF public.morlet_row_security_enabled(collection) THEN PERFORM public.morlet_enable_row_security(collection); END IF;
  RETURN rel;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_time_anchors_lock()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN
    RAISE EXCEPTION 'time anchors are written under READ COMMITTED (this transaction is %)',current_setting('transaction_isolation');
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('morlet-anchor-coll/'||TG_RELID,0));
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.morlet_time_anchors_append_only()
RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog AS $$
DECLARE parent boolean; collection regclass;
BEGIN
  IF TG_OP='DELETE' AND pg_trigger_depth()>1 THEN
    collection:=public.morlet_companion_parent(TG_RELID);
    IF collection IS NULL THEN RAISE EXCEPTION 'time anchor table % has no foreign key to its collection',TG_RELID::regclass; END IF;
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s WHERE recording_id=$1)',collection)
      INTO parent USING OLD.recording_id;
    IF NOT parent THEN RETURN OLD; END IF;
  END IF;
  RAISE EXCEPTION 'time anchors are append-only: revise or retract with morlet_revise_time_anchor';
END $$;
